questoes.codigo:
SELECT c.nome, p.id
FROM CLIENTE c
INNER JOIN PEDIDO p ON p.cliente_id = c.id;

SELECT nome
FROM CLIENTE
WHERE id NOT IN (SELECT cliente_id FROM PEDIDO);

